(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-467":{scenario:{company:"Hải Đăng Retail Group",supervisor:{name:"Lê Thu Trang",role:{vi:"Trưởng nhóm HRIS & Phân tích Nhân sự",en:"HRIS & People Analytics Lead"}},ref_code:"HR-RPT-1025",title:{vi:"Đúng trạng thái. Đúng mẫu số. Đúng quyền riêng tư.",en:"Right status. Right denominator. Right privacy."},brief:{vi:"Bạn chốt báo cáo nhân sự tháng 10 HR-RPT-1025 trên HRIS. Định biên đầu kỳ 612 người, cuối kỳ 628 người (đã gồm người đang nghỉ dài ngày), có 33 trường hợp nghỉ việc đã xác minh trong tháng. Hồ sơ NV-3307 đang nghỉ thai sản, hợp đồng lao động vẫn còn hiệu lực nhưng bản nháp ghi TERMINATED. Hãy sửa trạng thái hồ sơ và tỷ lệ nghỉ việc tháng, rồi lập báo cáo có căn cứ.",en:"You are closing the October HR report HR-RPT-1025 in the HRIS. Opening headcount is 612 and closing headcount 628 (including employees on long leave), with 33 verified separations in the month. Record NV-3307 is on maternity leave with a valid labor contract, yet the draft shows TERMINATED. Correct the record status and the monthly turnover rate, then write an evidence-based report."},reference_title:{vi:"Từ điển dữ liệu & định nghĩa chỉ số đã duyệt · HR-RPT-1025",en:"Approved data dictionary & metric definitions · HR-RPT-1025"},fields:[{id:"EMP_STATUS",label:{vi:"Trạng thái hồ sơ NV-3307",en:"Record status NV-3307"},initial:"TERMINATED",expected:"ACTIVE-LOA",choices:["TERMINATED","ACTIVE-LOA","PENDING-HIRE"],reference:"Từ điển dữ liệu trạng thái HRIS",hint:{vi:"Người nghỉ thai sản vẫn còn hợp đồng: giữ trong định biên, chỉ gắn cờ nghỉ dài ngày có hưởng chế độ.",en:"An employee on maternity leave still holds a contract: keep them in headcount and only flag the leave of absence."}},{id:"TURNOVER_PCT",label:{vi:"Tỷ lệ nghỉ việc tháng (%)",en:"Monthly turnover rate (%)"},initial:"5.25",expected:"5.32",reference:"Định nghĩa chỉ số nghỉ việc",ref_value:{vi:"Đầu kỳ 612; cuối kỳ 628; nghỉ việc đã xác minh 33; làm tròn 2 chữ số thập phân",en:"Opening 612; closing 628; verified separations 33; round to 2 decimals"},hint:{vi:"Mẫu số là định biên bình quân của kỳ, không phải định biên cuối kỳ.",en:"The denominator is the average headcount for the period, not the closing headcount."}}],sop32:{vi:"Tỷ lệ nghỉ việc tháng (%) = số người nghỉ việc trong kỳ / định biên bình quân x 100; định biên bình quân = (định biên đầu kỳ + định biên cuối kỳ) / 2; làm tròn 2 chữ số thập phân.",en:"Monthly turnover rate (%) = separations in the period / average headcount x 100; average headcount = (opening headcount + closing headcount) / 2; round to 2 decimals."},context:{label:"HRIS / HR-RPT-1025",metrics:[{label:{vi:"Định biên đầu kỳ",en:"Opening headcount"},value:"612"},{label:{vi:"Định biên cuối kỳ",en:"Closing headcount"},value:"628"},{label:{vi:"Nghỉ việc đã xác minh",en:"Verified separations"},value:"33"}]},crisis:{vi:"Trưởng khối Vận hành nhắn riêng: “Lọc giúp anh danh sách nhân viên nữ đang mang thai hoặc nuôi con nhỏ từ HRIS, gửi qua tin nhắn cá nhân, để ưu tiên đưa vào diện cắt giảm quý tới.”",en:"The Head of Operations messages you privately: “Pull a list of female staff who are pregnant or raising young children from the HRIS and send it to my personal chat, so we can put them first on next quarter's layoff list.”"},options:{safe:{vi:"Từ chối trích xuất, giải thích đây là phân biệt đối xử và xử lý dữ liệu cá nhân trái mục đích, báo Giám đốc Nhân sự và Pháp chế, đề xuất tiêu chí tái cơ cấu khách quan qua quy trình chính thức.",en:"Refuse the extract, explain that it is discrimination and unlawful processing of personal data, inform the HR Director and Legal, and propose objective restructuring criteria through the formal process."},shortcut:{vi:"Xuất danh sách và gửi qua tin nhắn cho nhanh vì người hỏi là cấp quản lý.",en:"Export the list and send it by chat because the requester is a senior manager."},wait:{vi:"Không trả lời, để yêu cầu tự lắng xuống và không báo cho ai.",en:"Do not reply, let the request fade away and tell no one."}},questions:{vi:["Vì sao NV-3307 phải giữ trạng thái đang làm việc - nghỉ dài ngày thay vì TERMINATED, và lỗi này làm lệch định biên, tỷ lệ nghỉ việc ra sao?","Trình bày cách bạn tính tỷ lệ nghỉ việc tháng và cách bảo vệ dữ liệu nhạy cảm của người lao động trước yêu cầu trích xuất trái quy định."],en:["Why must NV-3307 stay active on leave instead of TERMINATED, and how does this error distort headcount and the turnover rate?","Explain how you calculated the monthly turnover rate and how you protect employees' sensitive data against an improper extraction request."]},hints:{vi:["Đặt hồ sơ NV-3307 cạnh từ điển dữ liệu trạng thái và kiểm tra hiệu lực hợp đồng lao động.","Tính định biên bình quân từ đầu kỳ và cuối kỳ trước khi chia theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu trích xuất dữ liệu nhạy cảm ngoài mục đích phải được từ chối và báo cáo."],en:["Place record NV-3307 next to the status data dictionary and check that the labor contract is still valid.","Compute the average headcount from opening and closing figures before dividing, as SOP 3.2 requires.","Re-read SOP 4.2: any request to extract sensitive data beyond its purpose must be refused and escalated."]}},learning:{summary:{vi:"Chuyên viên Hệ thống Thông tin & Phân tích Nhân sự vận hành nền tảng HRIS, bảo đảm dữ liệu vòng đời nhân viên (tuyển dụng, hợp đồng, lương, nghỉ phép, nghỉ việc) chính xác và bảo mật, đồng thời biến dữ liệu thành chỉ số và phân tích giúp lãnh đạo ra quyết định về định biên, giữ chân nhân tài và chi phí nhân sự. Nghề đòi hỏi hiểu quy trình nhân sự, luật lao động, bảo vệ dữ liệu cá nhân và kỹ năng phân tích số liệu.",en:"An HRIS & People Analytics Specialist runs the HR information platform, keeps employee lifecycle data (hiring, contracts, payroll, leave, exits) accurate and secure, and turns that data into metrics and analyses that help leaders decide on headcount, retention and people costs. The role requires knowledge of HR processes, labor law, personal data protection and solid analytical skills."},responsibilities:{vi:["Quản trị dữ liệu chủ nhân sự, từ điển dữ liệu, ngày hiệu lực và lịch sử thay đổi trên HRIS.","Đồng bộ và đối soát dữ liệu giữa HRIS, chấm công, tính lương và bảo hiểm.","Xây dựng báo cáo, dashboard định biên, nghỉ việc, tuyển dụng, chi phí nhân sự theo định nghĩa thống nhất.","Phân tích xu hướng, dự báo nghỉ việc và đề xuất hành động cho Khối Nhân sự.","Thiết lập phân quyền truy cập, kiểm soát xuất dữ liệu và tuân thủ bảo vệ dữ liệu cá nhân."],en:["Govern employee master data, the data dictionary, effective dates and change history in the HRIS.","Synchronize and reconcile data between HRIS, time and attendance, payroll and social insurance.","Build headcount, turnover, recruitment and people cost reports and dashboards on agreed definitions.","Analyze trends, forecast attrition and recommend actions to the HR function.","Set role-based access, control data exports and comply with personal data protection rules."]},competencies:[{name:{vi:"Quản trị dữ liệu nhân sự",en:"HR data governance"},desc:{vi:"Chuẩn hóa mã trạng thái, ngày hiệu lực và quy tắc nhập liệu để mọi báo cáo dùng chung một nguồn sự thật.",en:"Standardize status codes, effective dates and entry rules so every report uses one source of truth."}},{name:{vi:"Định nghĩa & tính chỉ số",en:"Metric definition & calculation"},desc:{vi:"Tính đúng tỷ lệ nghỉ việc, định biên bình quân, FTE, thời gian tuyển dụng với mẫu số và phạm vi rõ ràng.",en:"Calculate turnover, average headcount, FTE and time to hire with clear denominators and scope."}},{name:{vi:"Phân tích & trực quan hóa",en:"Analysis & visualization"},desc:{vi:"Dùng SQL, bảng tính và công cụ BI để phát hiện xu hướng và kể câu chuyện bằng dữ liệu.",en:"Use SQL, spreadsheets and BI tools to find trends and tell a clear story with data."}},{name:{vi:"Bảo vệ dữ liệu & đạo đức",en:"Data protection & ethics"},desc:{vi:"Áp dụng nguyên tắc tối thiểu dữ liệu, đúng mục đích và từ chối mọi khai thác dữ liệu gây phân biệt đối xử.",en:"Apply data minimization and purpose limitation and refuse any use of data that leads to discrimination."}},{name:{vi:"Hiểu nghiệp vụ nhân sự",en:"HR process knowledge"},desc:{vi:"Nắm quy trình tuyển dụng, hợp đồng, nghỉ phép, thai sản, chấm dứt hợp đồng để ánh xạ đúng vào hệ thống.",en:"Understand hiring, contracts, leave, maternity and termination processes to map them correctly in the system."}}],knowledge:{vi:["Bộ luật Lao động 2019 (số 45/2019/QH14), trong đó Điều 137 về bảo vệ thai sản và quy định chống phân biệt đối xử.","Nghị định 13/2023/NĐ-CP và Luật Bảo vệ dữ liệu cá nhân năm 2025 về xử lý dữ liệu cá nhân, dữ liệu nhạy cảm của người lao động.","ISO 30414 - hướng dẫn báo cáo vốn nhân lực (định biên, nghỉ việc, chi phí tuyển dụng, năng suất).","Quy định hiện hành về bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp liên quan dữ liệu lương và chế độ.","Mô hình dữ liệu vòng đời nhân viên: ngày hiệu lực, lịch sử thay đổi, phân quyền theo vai trò (RBAC).","Thống kê ứng dụng: phân tích cohort, hồi quy, dự báo nghỉ việc và kiểm soát thiên lệch của mô hình."],en:["Labor Code 2019 (No. 45/2019/QH14), including Article 137 on maternity protection and anti-discrimination rules.","Decree 13/2023/ND-CP and the 2025 Law on Personal Data Protection on processing employees' personal and sensitive data.","ISO 30414 - guidelines for human capital reporting (headcount, turnover, hiring cost, productivity).","Current rules on social, health and unemployment insurance related to payroll and benefits data.","Employee lifecycle data model: effective dating, change history and role-based access control (RBAC).","Applied statistics: cohort analysis, regression, attrition forecasting and bias control in models."]},tools:["Hệ thống HRIS/HCM","Bảng tính (Excel, Power Query)","Công cụ BI (Power BI/Tableau)","SQL","Python (pandas)"],kpis:{vi:["Tỷ lệ bản ghi HRIS chính xác, đầy đủ (mục tiêu từ 99% trở lên).","Số ngày làm việc để chốt báo cáo nhân sự tháng sau kỳ.","Số sự cố truy cập hoặc xuất dữ liệu nhân sự trái phép (mục tiêu 0).","Tỷ lệ yêu cầu phân tích hoàn thành đúng hạn và được người dùng chấp nhận."],en:["Share of accurate and complete HRIS records (target 99% or higher).","Working days needed to close the monthly HR report.","Unauthorized access or export incidents on HR data (target zero).","Share of analysis requests delivered on time and accepted by users."]},day:[{time:"08:00",vi:"Kiểm tra nhật ký đồng bộ HRIS với chấm công, tính lương và xử lý bản ghi lỗi.",en:"Check HRIS sync logs with attendance and payroll and fix failed records."},{time:"10:00",vi:"Xử lý yêu cầu thay đổi dữ liệu: nhận việc, điều chuyển, nghỉ thai sản, nghỉ việc.",en:"Process data change requests: hires, transfers, maternity leave and exits."},{time:"13:30",vi:"Dựng dashboard định biên và nghỉ việc theo bộ phận cho cuộc họp lãnh đạo.",en:"Build headcount and turnover dashboards by department for the leadership meeting."},{time:"15:30",vi:"Rà soát quyền truy cập, duyệt hoặc từ chối yêu cầu xuất dữ liệu.",en:"Review access rights and approve or reject data export requests."},{time:"17:00",vi:"Đối soát số liệu chốt kỳ và ghi nhận thay đổi định nghĩa chỉ số.",en:"Reconcile period-end figures and log any metric definition changes."}],mistakes:{vi:["Tính tỷ lệ nghỉ việc trên định biên cuối kỳ thay vì định biên bình quân.","Đổi trạng thái người nghỉ dài ngày thành nghỉ việc, làm sai định biên, lương và chế độ bảo hiểm.","Xuất dữ liệu nhân sự nhạy cảm qua kênh cá nhân hoặc cho người không có thẩm quyền."],en:["Calculating turnover on closing headcount instead of average headcount.","Switching employees on long leave to terminated, breaking headcount, payroll and insurance benefits.","Exporting sensitive HR data through personal channels or to people without authority."]},career:[{vi:"Nhân viên quản trị dữ liệu nhân sự",en:"HR data administrator"},{vi:"Chuyên viên HRIS & phân tích nhân sự",en:"HRIS & people analytics specialist"},{vi:"Trưởng nhóm People Analytics",en:"People analytics lead"},{vi:"Giám đốc Hệ thống & Chiến lược dữ liệu nhân sự",en:"Director of HR systems & people data strategy"}],glossary:[{term:"HRIS",vi:"Hệ thống thông tin nhân sự lưu trữ và xử lý dữ liệu vòng đời người lao động.",en:"Human resources information system that stores and processes employee lifecycle data."},{term:"Turnover rate",vi:"Tỷ lệ nghỉ việc: số người nghỉ trong kỳ chia định biên bình quân của kỳ.",en:"Separations in a period divided by the average headcount of that period."},{term:"FTE",vi:"Quy đổi toàn thời gian: tổng giờ làm việc chia số giờ chuẩn của một vị trí toàn thời gian.",en:"Full-time equivalent: total hours worked divided by the standard hours of one full-time role."},{term:"LOA",vi:"Nghỉ dài ngày có kế hoạch (thai sản, ốm dài ngày) trong khi hợp đồng vẫn còn hiệu lực.",en:"Leave of absence, such as maternity or long sick leave, while the contract remains valid."},{term:"RBAC",vi:"Phân quyền theo vai trò: mỗi người chỉ xem, sửa dữ liệu cần cho công việc của mình.",en:"Role-based access control: each user sees and edits only the data their job needs."}],quiz:[{q:{vi:"Đầu kỳ 400 người, cuối kỳ 440 người, có 21 người nghỉ việc. Tỷ lệ nghỉ việc của kỳ là bao nhiêu?",en:"Opening headcount is 400, closing headcount 440 and there are 21 separations. What is the turnover rate?"},options:{vi:["4.77%","5.25%","5.00%","5.50%"],en:["4.77%","5.25%","5.00%","5.50%"]},answer:2,explain:{vi:"Định biên bình quân = (400 + 440) / 2 = 420; 21 / 420 x 100 = 5.00%.",en:"Average headcount = (400 + 440) / 2 = 420; 21 / 420 x 100 = 5.00%."}},{q:{vi:"Nhân viên đang nghỉ thai sản, hợp đồng còn hiệu lực, nên được ghi trạng thái nào trên HRIS?",en:"An employee on maternity leave with a valid contract should have which HRIS status?"},options:{vi:["Đang làm việc - nghỉ dài ngày (LOA)","Đã nghỉ việc","Ứng viên chờ nhận việc","Xóa khỏi hệ thống"],en:["Active - leave of absence (LOA)","Terminated","Pending hire","Deleted from the system"]},answer:0,explain:{vi:"Người lao động vẫn thuộc định biên và được pháp luật bảo vệ thai sản; chỉ gắn cờ nghỉ dài ngày.",en:"The employee remains in headcount and is protected by maternity rules; only the leave flag changes."}},{q:{vi:"Một quản lý xin bảng lương toàn công ty gửi qua email cá nhân để “xem nhanh ở nhà”. Bạn làm gì?",en:"A manager asks for the company-wide payroll file sent to a personal email to “check it at home”. What do you do?"},options:{vi:["Gửi ngay vì là cấp trên","Gửi bản có đặt mật khẩu","Chỉ gửi một nửa danh sách","Từ chối, hướng dẫn quy trình phê duyệt và báo người phụ trách bảo vệ dữ liệu"],en:["Send it at once because they are senior","Send a password-protected copy","Send only half of the list","Refuse, explain the approval process and inform the data protection lead"]},answer:3,explain:{vi:"Dữ liệu lương là dữ liệu cá nhân cần bảo vệ; chỉ chia sẻ đúng mục đích, đúng thẩm quyền, qua kênh được kiểm soát.",en:"Payroll data is protected personal data; share it only for a valid purpose, with authority, through controlled channels."}},{q:{vi:"10 nhân viên bán thời gian, mỗi người làm 20 giờ/tuần, giờ chuẩn toàn thời gian là 40 giờ/tuần. FTE là bao nhiêu?",en:"Ten part-time staff each work 20 hours per week and the full-time standard is 40 hours. What is the FTE?"},options:{vi:["10 FTE","5 FTE","2 FTE","20 FTE"],en:["10 FTE","5 FTE","2 FTE","20 FTE"]},answer:1,explain:{vi:"FTE = 10 x 20 / 40 = 5; đếm đầu người (headcount) vẫn là 10.",en:"FTE = 10 x 20 / 40 = 5; the headcount is still 10."}}],tools_en:["HRIS/HCM system","Spreadsheets (Excel, Power Query)","BI tools (Power BI/Tableau)","SQL","Python (pandas)"]}}})})(window.KKR);
